contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address account, uint256 amount, uint256 burnAmount) public {
        require(account != address(0), "account must not be zero");
        require(account != address(c), "account must not be the contract itself");
        require(amount > 0, "mint amount must be positive");
        require(burnAmount > 0, "burn amount must be positive");
        require(burnAmount <= amount, "burn amount must not exceed minted amount");

        uint256 tokenId = c.uniqueTokensOutstanding(); if (__ESBMC_reverted()) return;
        c.createGameItem("test item", "uri", false, true, 0, 0, 0); if (__ESBMC_reverted()) return;
        c.mint(tokenId, amount); if (__ESBMC_reverted()) return;
        c.setAllowedBurningAddresses(address(this)); if (__ESBMC_reverted()) return;

        uint256 balanceBefore = c.balanceOf(account, tokenId); if (__ESBMC_reverted()) return;
        c.burn(account, tokenId, burnAmount); if (__ESBMC_reverted()) return;
        uint256 balanceAfter = c.balanceOf(account, tokenId); if (__ESBMC_reverted()) return;

        assert(balanceAfter == balanceBefore - burnAmount);
    }

    receive() external payable {}
}

